// -----------------------------------------------------------------------------
// UNIVERSAL Elmo Parser + SR decode
//
// Ключевые принципы:
//   * msg.topic НИКОГДА не меняется - фронт фильтрует сам
//   * Единый токенизатор для всех форматов ответов Elmo:
//       Формат A: PARAM=VALUE[;PARAM=VALUE;...] -> "SP=9102;AC=910;DC=910"
//       Формат B: PARAM;VALUE[;PARAM;VALUE;...] -> "MS;0;PX;2808089"
//       (\r\n внутри строки нормализуется в ";")
//   * Нет init-буфера: SP/AC/DC идут напрямую в payload
//   * buildPollData возвращает полный снимок poll-буфера с оригинальным topic
// -----------------------------------------------------------------------------

function decodeSR(sr) {
    var bin = (sr >>> 0).toString(2).padStart(32, "0");
    var lowBits = bin.slice(-4);
    var amplifierCode = sr & 0xF;
    var errors = [];
    var amplifierCodeMap = {
        0: "Ошибок нет",
        3: "Пониженное напряжение",
        5: "Повышенное напряжение",
        7: "Safety / STO (no air / STO interlock)",
        9: "Ошибка датчика",
        11: "Короткое замыкание",
        12: "Abort",
        13: "Перегрев привода",
        14: "Перегрев двигателя",
        15: "Дополнительный Abort",
    };
    var amplifierText = amplifierCodeMap.hasOwnProperty(amplifierCode)
        ? amplifierCodeMap[amplifierCode]
        : ("Неизвестный код ошибки SR: " + amplifierCode);

    if (amplifierCode !== 0) {
        errors.push("SR[0-3]=" + amplifierCode + ": " + amplifierText);
    }

    return {
        raw: sr,
        binary: bin,
        amplifier_bits_0_3: lowBits,
        amplifier_code: amplifierCode,
        amplifier_text: amplifierText,
        ok: amplifierCode === 0,
        errors: errors,
        summary: amplifierCode === 0 ? "Ошибок нет" : ("Код " + amplifierCode + ": " + amplifierText),
    };
}

function parseElmoNumber(value) {
    var text = String(value || "").trim();
    if (!text) return NaN;
    return Number(text);
}

function configuredAngleDeg(value, fallback) {
    if (!value || typeof value !== "object") return fallback;
    if (value.decimalDeg !== undefined && value.decimalDeg !== null && value.decimalDeg !== "") {
        var decimal = Number(value.decimalDeg);
        return isFinite(decimal) ? Math.abs(decimal) : fallback;
    }
    if (value.rad !== undefined && value.rad !== null && value.rad !== "") {
        var rad = Number(value.rad);
        return isFinite(rad) ? Math.abs(rad * 180 / Math.PI) : fallback;
    }
    var deg = Number(value.deg) || 0;
    var min = Math.abs(Number(value.min) || 0);
    var sec = Math.abs(Number(value.sec) || 0);
    return Math.abs(deg) + min / 60 + sec / 3600;
}

function configuredSpeedRange(resolution) {
    var settings = global.get("settings") || {};
    var ranges = (settings.advanced && settings.advanced.rotationSpeedRanges) || global.get("drive_speed_ranges") || {};
    var range = ranges[resolution];
    if (!range || !range.min || !range.max) return null;
    var defaultMin = (resolution === "high") ? (1 / 3600) : 10;
    var defaultMax = (resolution === "high") ? 20 : 360;
    return {
        minDeg: configuredAngleDeg(range.min, defaultMin),
        maxDeg: configuredAngleDeg(range.max, defaultMax)
    };
}

function buildDriveLimitsFromPoll(poll) {
    var resolution = poll.resolution || flow.get("resolution") || "high";
    var ticksPerDeg = (resolution === "high") ? (262144000 / 360) : (6553600 / 360);
    var cfg = configuredSpeedRange(resolution) || {};
    var speedMinDeg = cfg.minDeg !== undefined ? cfg.minDeg : ((resolution === "high") ? (1 / 3600) : 10);
    var rangeMaxDeg = cfg.maxDeg !== undefined ? cfg.maxDeg : ((resolution === "high") ? 20 : 360);
    var defaultVh2 = Math.floor(rangeMaxDeg * ticksPerDeg);
    var defaultAccel = (resolution === "high") ? 131072000 : 3276800;
    var driveSpeedMaxTicks = poll.vh2 !== undefined ? Number(poll.vh2) : defaultVh2;
    var speedMaxTicks = Math.min(Math.round(driveSpeedMaxTicks), Math.floor(rangeMaxDeg * ticksPerDeg));
    var speedMinTicks = Math.ceil(speedMinDeg * ticksPerDeg);
    var accelMaxTicks = Math.min(
        poll.sd !== undefined ? Math.round(Number(poll.sd)) : defaultAccel,
        poll.vh1 !== undefined ? Math.round(Number(poll.vh1)) : defaultAccel,
        poll.vl1 !== undefined ? Math.round(Number(poll.vl1)) : defaultAccel
    );
    return {
        resolution: resolution,
        ticks_per_deg: ticksPerDeg,
        speed_min_deg: speedMinDeg,
        speed_max_deg: speedMaxTicks / ticksPerDeg,
        speed_min_ticks: speedMinTicks,
        speed_max_ticks: speedMaxTicks,
        accel_min_ticks: 0,
        accel_max_ticks: accelMaxTicks,
        accel_max_deg: accelMaxTicks / ticksPerDeg,
        decel_min_ticks: 0,
        decel_max_ticks: accelMaxTicks,
        decel_max_deg: accelMaxTicks / ticksPerDeg,
    };
}

function estimateVelocityFromSamples(samples) {
    if (!Array.isArray(samples) || samples.length < 2) return null;
    var last = samples[samples.length - 1];
    var first = null;
    for (var i = samples.length - 2; i >= 0; i--) {
        var candidate = samples[i];
        var dtUs = Number(last.tmUs) - Number(candidate.tmUs);
        if (!(dtUs > 0)) continue;
        if (dtUs > 3000000) break;
        first = candidate;
    }
    if (!first) return null;
    var spanUs = Number(last.tmUs) - Number(first.tmUs);
    if (spanUs < 200000) return null;
    var ticksPerSec = (Number(last.positionTicks) - Number(first.positionTicks)) * 1000000 / spanUs;
    if (!isFinite(ticksPerSec)) return null;
    return {
        ticksPerSec: ticksPerSec,
        dtSec: spanUs / 1000000,
        positionDeltaTicks: Number(last.positionTicks) - Number(first.positionTicks),
    };
}

function updateVelocityEstimate(poll, hasFreshSample) {
    var resolution = poll.resolution || flow.get("resolution") || "high";
    var rawVelocity = Number(poll.velocity);
    poll.velocity_raw = isFinite(rawVelocity) ? rawVelocity : 0;

    if (hasFreshSample) {
        var positionTicks = Number(poll.position);
        var tmUs = Number(poll.tm_us);
        if (isFinite(positionTicks) && isFinite(tmUs)) {
            var sample = { resolution: resolution, positionTicks: positionTicks, tmUs: tmUs };
            var samples = flow.get("velocity_samples") || [];
            samples = samples.filter(function (s) {
                if (!s || s.resolution !== resolution) return false;
                var oldTm = Number(s.tmUs);
                var oldPx = Number(s.positionTicks);
                if (!isFinite(oldTm) || !isFinite(oldPx)) return false;
                var ageUs = tmUs - oldTm;
                return ageUs >= 0 && ageUs <= 5000000;
            });
            samples.push(sample);
            flow.set("velocity_samples", samples);

            var estimate = estimateVelocityFromSamples(samples);
            if (estimate) {
                poll.velocity_derived = Math.round(estimate.ticksPerSec * 1000) / 1000;
                poll.velocity_derived_dt_sec = estimate.dtSec;
                poll.velocity_derived_delta_ticks = estimate.positionDeltaTicks;
            }
        }
    }

    if (resolution === "low" && poll.velocity_derived !== undefined && poll.velocity_derived !== null) {
        poll.velocity_selected = poll.velocity_derived;
        poll.velocity_source = "px_tm";
    } else {
        poll.velocity_selected = poll.velocity_raw;
        poll.velocity_source = "vx";
    }
}

function applyParam(poll, param, value) {
    switch (param) {
        case "PX": poll.position = value; break;
        case "TM": poll.tm_us = value; break;
        case "VX": poll.velocity = value; break;
        case "MS": poll.ms = value; break;
        case "SO": poll.so = (value === 1); break;
        case "MO": poll.mo = (value === 1); break;
        case "SP": poll.sp = value; break;
        case "AC": poll.ac = value; break;
        case "DC": poll.dc = value; break;
        case "JV": poll.jv = value; break;
        case "JP": poll.jp = value; break;
        case "TR[1]": poll.tr1 = value; break;
        case "TR[3]": poll.tr3 = value; break;
        case "PA": poll.target_position = value; break;
        case "PR": poll.relative_position = value; break;

        case "CA[18]": poll.ca18 = value; break;
        case "S1[5]": poll.s1_5 = value; break;
        case "KP[2]": poll.kp2 = value; break;
        case "SD": poll.sd = value; break;
        case "QS": poll.qs = value; break;
        case "VH[1]": poll.vh1 = value; break;
        case "VL[1]": poll.vl1 = value; break;
        case "VH[2]": poll.vh2 = value; break;
        case "ER[3]": poll.er3 = value; break;
        case "ER[2]": poll.er2 = value; break;
        case "EC": poll.ec = value; break;
        case "MF": poll.mf = value; break;
        case "EE[5]": poll.ee5 = value; break;
        case "HM[1]": poll.hm1 = value; break;

        case "AF":
            poll.af = value;
            poll.remote_control_ok = (value === 0);
            break;

        case "SR":
            poll.sr = value;
            poll.sr_decoded = decodeSR(value);
            break;

        // OL[1]: мануал раздел 4 - 0=высокое, 1=низкое
        case "OL[1]":
            poll.ol1 = value;
            poll.resolution = (value === 0) ? "high" : "low";
            flow.set("resolution", poll.resolution);
            global.set("current_range", poll.resolution);
            break;

        // OL[2]: мануал раздел 7 - тормоз внешней оси БУН
        // 0=тормоз выключен (ось свободна), 1=тормоз включён (ось зафиксирована)
        case "OL[2]":
            poll.ol2 = value;
            poll.bun_brake = (value === 1);
            flow.set("bun_brake", poll.bun_brake);
            break;

        default:
            node.log("Unknown param: " + param);
    }
}

function isStateWriteEcho(param) {
    return param === "MO" || param === "SO" || param === "SR";
}

function buildPollData(poll) {
    var limits = buildDriveLimitsFromPoll(poll);
    var selectedVelocity = poll.velocity_selected !== undefined ? poll.velocity_selected : (poll.velocity !== undefined ? poll.velocity : 0);
    var velocityDegPerSec = limits.ticks_per_deg ? (Number(selectedVelocity) || 0) / limits.ticks_per_deg : 0;
    flow.set("drive_limits", limits);
    global.set("drive_limits", limits);
    global.set("current_range", limits.resolution);
    return {
        topic: msg.topic,   // оригинальный топик, не меняем
        payload: {
            position: poll.position !== undefined ? poll.position : 0,
            tm_us: poll.tm_us !== undefined ? poll.tm_us : null,
            velocity: selectedVelocity,
            velocity_raw: poll.velocity_raw !== undefined ? poll.velocity_raw : (poll.velocity !== undefined ? poll.velocity : 0),
            velocity_derived: poll.velocity_derived !== undefined ? poll.velocity_derived : null,
            velocity_source: poll.velocity_source || "vx",
            velocity_deg_per_sec: velocityDegPerSec,
            ms: poll.ms !== undefined ? poll.ms : 3,
            so: poll.so !== undefined ? poll.so : false,
            mo: poll.mo !== undefined ? poll.mo : false,
            af: poll.af !== undefined ? poll.af : 0,
            remote_control_ok: poll.remote_control_ok !== undefined ? poll.remote_control_ok : true,
            sp: poll.sp !== undefined ? poll.sp : 0,
            ac: poll.ac !== undefined ? poll.ac : 0,
            dc: poll.dc !== undefined ? poll.dc : 0,
            jv: poll.jv !== undefined ? poll.jv : 0,
            jp: poll.jp !== undefined ? poll.jp : 0,
            tr1: poll.tr1 !== undefined ? poll.tr1 : 0,
            tr3: poll.tr3 !== undefined ? poll.tr3 : 0,
            sr: poll.sr !== undefined ? poll.sr : 0,
            ec: poll.ec !== undefined ? poll.ec : 0,
            mf: poll.mf !== undefined ? poll.mf : 0,
            ee5: poll.ee5 !== undefined ? poll.ee5 : 0,
            ca18: poll.ca18 !== undefined ? poll.ca18 : 0,
            s1_5: poll.s1_5 !== undefined ? poll.s1_5 : 0,
            kp2: poll.kp2 !== undefined ? poll.kp2 : 0,
            sd: poll.sd !== undefined ? poll.sd : 0,
            qs: poll.qs !== undefined ? poll.qs : 0,
            vh1: poll.vh1 !== undefined ? poll.vh1 : 0,
            vl1: poll.vl1 !== undefined ? poll.vl1 : 0,
            vh2: poll.vh2 !== undefined ? poll.vh2 : 0,
            er3: poll.er3 !== undefined ? poll.er3 : 0,
            er2: poll.er2 !== undefined ? poll.er2 : 0,
            hm1: poll.hm1 !== undefined ? poll.hm1 : 0,
            target_position: poll.target_position !== undefined ? poll.target_position : 0,
            relative_position: poll.relative_position !== undefined ? poll.relative_position : 0,
            sr_status: poll.sr_decoded || {
                raw: 0,
                binary: "00000000000000000000000000000000",
                amplifier_bits_0_3: "0000",
                amplifier_code: 0,
                amplifier_text: "Ошибок нет",
                ok: true,
                errors: [],
                summary: "Ошибок нет",
            },
            torque: 0,
            resolution: poll.resolution || flow.get("resolution") || "high",
            drive_limits: limits,
            // Тормоз БУН (OL[2]): передаём в UI для синхронизации тумблера
            bun_brake: poll.bun_brake !== undefined
                ? poll.bun_brake
                : (flow.get("bun_brake") || false),
        },
    };
}

// -----------------------------------------------------------------------------
// ВХОДНОЙ ПОТОК
// -----------------------------------------------------------------------------

var raw = String(msg.payload || "");
raw = raw.replace(/\u0000/g, "").trim();

if (!raw) return null;

raw = raw.replace(/^"+|"+$/g, "");

if (raw === ";" || raw === "BG" || raw === ":?") {
    return null;
}

// Нормализация: \r\n -> ";", схлопываем повторные ";", убираем крайние
raw = raw.replace(/[\r\n]+/g, ";")
    .replace(/;{2,}/g, ";")
    .replace(/^;|;$/g, "");

if (!raw) return null;

var tokens = raw.split(";")
    .map(function (s) { return s.trim(); })
    .filter(Boolean);

if (tokens.length === 0) return null;

var poll = flow.get("poll_buffer") || {};
var frameHasTm = false;
var frameHasPx = false;

// Поддерживаем смешанный ответ:
//   "SP=9102;AC=910;MS;0;PX;2808089"
// Это важно для driveInit, где в одном пакете могут встретиться эхо записи
// и ответы на чтение состояния.
for (var i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    var eqIdx = token.indexOf("=");

    if (eqIdx !== -1) {
        var pA = token.slice(0, eqIdx).trim().toUpperCase();
        var vA = parseElmoNumber(token.slice(eqIdx + 1));
        if (!isNaN(vA)) {
            if (pA === "TM") frameHasTm = true;
            if (pA === "PX") frameHasPx = true;
            if (!isStateWriteEcho(pA)) applyParam(poll, pA, vA);
        }
        continue;
    }

    if (i + 1 >= tokens.length || tokens[i + 1].indexOf("=") !== -1) {
        continue;
    }

    var pB = token.toUpperCase();
    var vB = parseElmoNumber(tokens[i + 1]);
    if (!isNaN(vB)) {
        if (pB === "TM") frameHasTm = true;
        if (pB === "PX") frameHasPx = true;
        applyParam(poll, pB, vB);
        i++;
    }
}

updateVelocityEstimate(poll, frameHasTm && frameHasPx);
flow.set("poll_buffer", poll);

return buildPollData(poll);

// Normalize settings loaded by the file-in node and seed global context.
// Normalize settings, compute derived angle fields, and update global context.
var settings = msg.payload || {};
if (typeof settings === 'string') {
    try { settings = JSON.parse(settings); }
    catch (e) {
        node.warn('settings JSON parse failed: ' + e.message);
        settings = {};
    }
}

var DEFAULTS = {
    general: {
        remoteControl: false,
        angleCorrectionEnabled: false,
        language: 'Russian',
        angleSavingMode: 'header',
        speedReadyTolerancePercent: 5
    },
    advanced: {
        dataDurationSec: 60,
        rawDataPollHz: 30,
        fastRawPollingEnabled: true,
        fastStableSamples: 3,
        fastStableToleranceTicks: 1000,
        encoderSwitchHysteresisDegSec: 5,
        speedRangeToleranceDegSec: 5,
        speedReadyToleranceDegSec: 0.5,
        speedStableTimeMs: 1000,
        speedReachTimeoutMs: 10000,
        rotationSpeedRanges: {
            high: {
                min: { deg: 0, min: 0, sec: 1.000001, decimalDeg: 0.000277778, rad: 0.000004848141 },
                max: { deg: 20, min: 0, sec: 0, decimalDeg: 20, rad: 0.349065850399 }
            },
            low: {
                min: { deg: 10, min: 0, sec: 0, decimalDeg: 10, rad: 0.174532925199 },
                max: { deg: 360, min: 0, sec: 0, decimalDeg: 360, rad: 6.28318530718 }
            }
        },
        rotationSpeed: null,
        tiltAngle: {
            min: { deg: 0, min: 0, sec: 0, decimalDeg: 0, rad: 0 },
            max: { deg: 0, min: 0, sec: 0, decimalDeg: 0, rad: 0 }
        },
        encoderSwitchSpeed: { deg: 20, min: 0, sec: 0, decimalDeg: 20, rad: 0.349065850399 },
        BEPcoeffs: [0, 0, 0, 0, 0],
        aerostaticSupportDiagram: '',
        encoderCalibrationLines: ''
    }
};

function clone(v) { return JSON.parse(JSON.stringify(v)); }
function merge(base, patch) {
    var out = clone(base);
    patch = patch && typeof patch === 'object' ? patch : {};
    Object.keys(patch).forEach(function(k) {
        if (patch[k] && typeof patch[k] === 'object' && !Array.isArray(patch[k]) && out[k] && typeof out[k] === 'object' && !Array.isArray(out[k])) {
            out[k] = merge(out[k], patch[k]);
        } else {
            out[k] = patch[k];
        }
    });
    return out;
}
function number(v, fallback) {
    var x = Number(v);
    return isFinite(x) ? x : fallback;
}
function languageName(v) {
    var s = String(v || '').toLowerCase();
    return (s === 'english' || s === 'en') ? 'English' : 'Russian';
}
function dmsToDecimal(v) {
    v = v || {};
    var sign = number(v.deg, 0) < 0 ? -1 : 1;
    return sign * (Math.abs(number(v.deg, 0)) + number(v.min, 0) / 60 + number(v.sec, 0) / 3600);
}
function fillDms(v, decimalDeg) {
    var sign = decimalDeg < 0 ? -1 : 1;
    var abs = Math.abs(decimalDeg);
    var deg = Math.floor(abs);
    var minutesFloat = (abs - deg) * 60;
    var min = Math.floor(minutesFloat);
    var sec = (minutesFloat - min) * 60;
    v.deg = sign * deg;
    v.min = min;
    v.sec = Number(sec.toFixed(6));
}
function normalizeAngle(v, fallback) {
    v = merge(fallback || { deg: 0, min: 0, sec: 0, decimalDeg: 0, rad: 0 }, v || {});
    var decimalDeg;
    if (v.decimalDeg !== undefined && v.decimalDeg !== null && v.decimalDeg !== '') {
        decimalDeg = number(v.decimalDeg, dmsToDecimal(v));
    } else if (v.rad !== undefined && v.rad !== null && v.rad !== '') {
        decimalDeg = number(v.rad, 0) * 180 / Math.PI;
    } else {
        decimalDeg = dmsToDecimal(v);
    }
    v.decimalDeg = Number(decimalDeg.toFixed(9));
    v.rad = Number((decimalDeg * Math.PI / 180).toFixed(12));
    fillDms(v, decimalDeg);
    return v;
}
function normalizeRange(range, fallback) {
    var min = normalizeAngle(range && range.min, fallback.min);
    var max = normalizeAngle(range && range.max, fallback.max);
    if (!(Math.abs(min.decimalDeg) > 0)) min = normalizeAngle(null, fallback.min);
    if (!(Math.abs(max.decimalDeg) > 0)) max = normalizeAngle(null, fallback.max);
    return { min: min, max: max };
}
function ticksPerDeg(res) { return (res === 'high') ? (262144000 / 360) : (6553600 / 360); }
function rangeLimits(range, res) {
    var tpd = ticksPerDeg(res);
    return {
        resolution: res,
        ticks_per_deg: tpd,
        speed_min_deg: range.min.decimalDeg,
        speed_max_deg: range.max.decimalDeg,
        speed_min_ticks: Math.ceil(Math.abs(range.min.decimalDeg) * tpd),
        speed_max_ticks: Math.floor(Math.abs(range.max.decimalDeg) * tpd)
    };
}

settings = merge(DEFAULTS, settings);
settings.general.language = languageName(settings.general.language);
settings.general.angleSavingMode = settings.general.angleSavingMode === 'none' ? 'none' : 'header';
settings.general.speedReadyTolerancePercent = Math.min(100, Math.max(0, number(settings.general.speedReadyTolerancePercent, 5)));
var obsoleteReadPeriodKeys = ['readPeriodRotation', 'readPeriodTilt', 'readPeriodBEP'];
settings.advanced.dataDurationSec = Math.max(1, number(settings.advanced.dataDurationSec, 60));
obsoleteReadPeriodKeys.forEach(function(key) { delete settings.advanced[key]; });
settings.advanced.rawDataPollHz = Math.min(30, Math.max(1, number(settings.advanced.rawDataPollHz, 30)));
settings.advanced.fastRawPollingEnabled = settings.advanced.fastRawPollingEnabled !== false;
settings.advanced.fastStableSamples = Math.min(50, Math.max(1, Math.round(number(settings.advanced.fastStableSamples, 3))));
settings.advanced.fastStableToleranceTicks = Math.max(0, number(settings.advanced.fastStableToleranceTicks, 1000));
settings.advanced.encoderSwitchHysteresisDegSec = Math.max(0, number(settings.advanced.encoderSwitchHysteresisDegSec, 5));
settings.advanced.speedRangeToleranceDegSec = Math.max(0, number(settings.advanced.speedRangeToleranceDegSec, 5));
settings.advanced.speedReadyToleranceDegSec = Math.max(0, number(settings.advanced.speedReadyToleranceDegSec, 0.5));
settings.advanced.speedStableTimeMs = Math.max(0, Math.round(number(settings.advanced.speedStableTimeMs, 1000)));
settings.advanced.speedReachTimeoutMs = Math.max(1, Math.round(number(settings.advanced.speedReachTimeoutMs, 10000)));

if (!settings.advanced.rotationSpeedRanges && settings.advanced.rotationSpeed) {
    settings.advanced.rotationSpeedRanges = { high: settings.advanced.rotationSpeed, low: DEFAULTS.advanced.rotationSpeedRanges.low };
}
settings.advanced.rotationSpeedRanges = {
    high: normalizeRange(settings.advanced.rotationSpeedRanges.high, DEFAULTS.advanced.rotationSpeedRanges.high),
    low: normalizeRange(settings.advanced.rotationSpeedRanges.low, DEFAULTS.advanced.rotationSpeedRanges.low)
};
settings.advanced.rotationSpeed = settings.advanced.rotationSpeedRanges.high;
settings.advanced.tiltAngle = normalizeRange(settings.advanced.tiltAngle, DEFAULTS.advanced.tiltAngle);
settings.advanced.encoderSwitchSpeed = normalizeAngle(settings.advanced.encoderSwitchSpeed, DEFAULTS.advanced.encoderSwitchSpeed);
if (!(Math.abs(settings.advanced.encoderSwitchSpeed.decimalDeg) > 0)) {
    settings.advanced.encoderSwitchSpeed = normalizeAngle(null, DEFAULTS.advanced.encoderSwitchSpeed);
}
if (!Array.isArray(settings.advanced.BEPcoeffs)) settings.advanced.BEPcoeffs = [0, 0, 0, 0, 0];
while (settings.advanced.BEPcoeffs.length < 5) settings.advanced.BEPcoeffs.push(0);
settings.advanced.BEPcoeffs = settings.advanced.BEPcoeffs.slice(0, 5).map(function(v) { return number(v, 0); });

global.set('settings', settings);
global.set('ui_language', settings.general.language === 'English' ? 'english' : 'russian');
global.set('drive_speed_ranges', settings.advanced.rotationSpeedRanges);
global.set('recording_duration_sec', settings.advanced.dataDurationSec);
global.set('raw_data_poll_hz', settings.advanced.rawDataPollHz);
global.set('speed_ready_tolerance_percent', settings.general.speedReadyTolerancePercent);
var currentRange = global.get('current_range') || 'high';
global.set('drive_limits_override', rangeLimits(settings.advanced.rotationSpeedRanges[currentRange] || settings.advanced.rotationSpeedRanges.high, currentRange));

msg.settings = settings;
msg.payload = settings;
return msg;

/*
var ch_in = global.get("v2_inp"),
    ch_out = global.get("v2_out"),
    calib_use = global.get("use_calib");

msg.calib_use = calib_use;

msg.topic = "bun_angle";

