}
function getRecordingDurationSec(value) {
    var settings = global.get('settings') || {};
    var configured = value !== undefined && value !== null && value !== ''
        ? value
        : (global.get('recording_duration_sec') || (settings.advanced && settings.advanced.dataDurationSec) || 60);
    var sec = Math.round(safeNumber(configured, 60));
