    state.selectedProtocol = state.selectedProtocol || '';
    state.selectedFile = state.selectedFile || '';
    state.selectedKind = state.selectedKind || 'protocol';
    state.selectedName = state.selectedName || basename(state.selectedFile || state.selectedProtocol);
    state.error = state.error || '';
