}
function resolveDataFile(reference) {
    var ref = String(reference || '').trim();
    if (!ref) return '';
    if (/^[A-Za-z]:\\/.test(ref)) return ref;
    if (ref.indexOf('\\') >= 0 || ref.indexOf('/') >= 0) return ref;
    return 'C:\\NC3\\data\\' + ref;
}
function parseListPayload(payload) {
    var raw = String(payload || '').trim();
    if (!raw) return [];
    var parsed;
    try {
        parsed = JSON.parse(raw);
    } catch (err) {
        node.warn('Cannot parse protocol list JSON: ' + err.message);
        return [];
    }
    if (!Array.isArray(parsed)) parsed = parsed ? [parsed] : [];
    return parsed
        .filter(function(item) { return item && item.path; })
        .map(function(item) {
            return {
                name: item.name || basename(item.path),
