}
function parseFileRows(text, kind, filePath, selectedProtocol) {
    var lines = String(text || '').replace(/\r/g, '').split('\n');
    var rows = [];
    var inDataSection = false;
    for (var i = 0; i < lines.length; i++) {
        var line = lines[i];
        var trimmed = line.trim();
        if (!trimmed) {
            rows.push({ kind: 'blank', text: '' });
            continue;
        }
        if (trimmed === '=====') {
            rows.push({ kind: 'marker', text: line });
            continue;
        }
        if (trimmed === '-------------------') {
            inDataSection = true;
            rows.push({ kind: 'separator', text: line });
            continue;
        }
        if (kind === 'protocol' && inDataSection) {
            var match = trimmed.match(/^([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)(?:\s+([^#]+?\.txt))?\s*(#.*)?$/);
            if (match) {
                var dataFileRef = match[3] ? match[3].trim() : '';
                if (dataFileRef) {
                    var dataPath = resolveDataFile(dataFileRef);
                    rows.push({
                        kind: 'protocol-link',
                        speed: match[1],
                        error: match[2],
                        dataFileName: basename(dataFileRef),
                        dataFilePath: dataPath,
                        comment: match[4] || ''
                    });
                    continue;
                }
            }
        }
        rows.push({
            kind: trimmed.charAt(0) === '#' ? 'comment' : 'text',
            text: line
        });
    }
    return rows;
}
function finalizeRecording(protocolFile, saveRaw) {
    var buf = global.get('angle_buffer') || [];
    var durationSec = getRecordingDurationSec();
    if (buf.length) {
        var endT = safeNumber(buf[buf.length - 1].t, 0);
        var minT = endT - durationSec;
        buf = buf.filter(function(point) { return safeNumber(point.t, 0) >= minT; });
        global.set('angle_buffer', buf);
    }
    setRecordingFlags(false, false);

    if (buf.length < 2) {
        pushLog('Ошибка: недостаточно данных (' + buf.length + ' точек)', 'error');
        return { protocolMsg: null, dataMsg: null };
    }

    var n = buf.length;
    var tMean = 0;
    var aMean = 0;
    for (var bi = 0; bi < n; bi++) {
        tMean += safeNumber(buf[bi].t, 0);
        aMean += safeNumber(buf[bi].angle, 0);
    }
    tMean /= n;
    aMean /= n;

    var num = 0;
    var den = 0;
    for (var bj = 0; bj < n; bj++) {
        var dt = safeNumber(buf[bj].t, 0) - tMean;
        num += dt * (safeNumber(buf[bj].angle, 0) - aMean);
        den += dt * dt;
    }

    var omega = (den > 0) ? num / den : 0;
    var rangeForSpeed = global.get('current_range') || 'high';
    var ticksPerRev = (rangeForSpeed === 'high') ? 262144000 : 6553600;
    var targetTicks = safeNumber(global.get('velocity_setpoint_ticks'), 0);
    var targetDegPerSec = targetTicks / ticksPerRev * 360.0;
    var errPct = targetDegPerSec !== 0 ? Math.abs((omega - targetDegPerSec) / targetDegPerSec * 100) : 0;

    if (saveRaw) {
        var dataStamp = tsFile(now);
        var dataFile = 'C:\\NC3\\data\\data_' + dataStamp + '.txt';
        var lineText = buf.map(function(point) {
            return safeNumber(point.t, 0).toFixed(3) + '  ' + safeNumber(point.angle, 0).toFixed(6);
        }).join('\n');

        var dataContent = [
            '=====',
            '# Идентификатор файла данных ' + dataStamp,
            '# Создан: ' + nowStr(now),
            'Файл_протокола     ' + basename(protocolFile),
            'Скорость_задания   ' + targetDegPerSec.toFixed(6) + ' # градус/с',
            'Скорость_измеренная ' + omega.toFixed(6) + ' # градус/с',
            'Погрешность        ' + errPct.toFixed(4) + ' # %',
            'Точек_данных       ' + buf.length,
            'Длительность_записи ' + durationSec.toFixed(3) + ' # секунда',
            '-------------------',
            'Время  Угол # секунда  градус',
            lineText,
            '=====',
        ].join('\n') + '\n';

        var shortName = basename(dataFile);
        var protoRowWithData = omega.toFixed(6) + '  ' + errPct.toFixed(4) + '  ' + shortName + ' # градус/с  %  файл исходных данных\n';
        pushLog('Записано: omega=' + omega.toFixed(4) + ' град/с, delta=' + errPct.toFixed(2) + '% -> ' + shortName, 'record');
        return {
            protocolMsg: { payload: protoRowWithData, filename: protocolFile },
            dataMsg: { payload: dataContent, filename: dataFile }
        };
    }

    var protoRow = omega.toFixed(6) + '  ' + errPct.toFixed(4) + ' # градус/с  %\n';
    pushLog('Записано: omega=' + omega.toFixed(4) + ' град/с, delta=' + errPct.toFixed(2) + '%', 'record');
    return { protocolMsg: { payload: protoRow, filename: protocolFile }, dataMsg: null };
}

