    if (!requestedFile) return null;

    var openState = getJournalState();
    openState.selectedFile = requestedFile;
    openState.selectedKind = requested.kind === 'data' ? 'data' : 'protocol';
    openState.selectedName = basename(requestedFile);
    if (openState.selectedKind === 'protocol') {
        openState.selectedProtocol = requestedFile;
    } else if (requested.selectedProtocol) {
        openState.selectedProtocol = requested.selectedProtocol;
    }
    openState.error = '';
    saveJournalState(openState);
    return [
        null,
        null,
        getJournalMessage(openState),
        null,
        {
            topic: 'journal_open_file',
            journalAction: 'file_result',
            filename: requestedFile,
            kind: openState.selectedKind,
            selectedProtocol: openState.selectedProtocol
        }
    ];
}

if (topic === 'journal_open_file' && msg.journalAction === 'file_result') {
    var loadedState = getJournalState();
    loadedState.selectedFile = msg.filename || loadedState.selectedFile;
    loadedState.selectedKind = msg.kind || loadedState.selectedKind || 'protocol';
    loadedState.selectedName = basename(loadedState.selectedFile);
    if (loadedState.selectedKind === 'protocol') {
        loadedState.selectedProtocol = loadedState.selectedFile;
    } else if (msg.selectedProtocol) {
        loadedState.selectedProtocol = msg.selectedProtocol;
    }

    if (msg.error) {
        loadedState.rows = [];
        loadedState.error = String(msg.error.message || msg.error || 'Не удалось открыть файл');
        saveJournalState(loadedState);
        return [null, null, getJournalMessage(loadedState), null, null];
    }

    var fileText = '';
    if (typeof msg.payload === 'string') fileText = msg.payload;
    else if (msg.payload !== undefined && msg.payload !== null) fileText = String(msg.payload);

    loadedState.rows = parseFileRows(fileText, loadedState.selectedKind, loadedState.selectedFile, loadedState.selectedProtocol);
    loadedState.error = '';
    saveJournalState(loadedState);
    return [null, null, getJournalMessage(loadedState), null, null];
}

return null;

// Legacy stub. Settings are persisted in the SETTINGS flow via a file node.
if (msg.topic !== 'save_settings') return null;
global.set('settings', msg.payload);
return { topic: 'settings_saved', payload: msg.payload };

var topic = msg.topic;
var protocolTopics = {
    open_protocol: true,
    close_protocol: true,
    start_recording: true,
    stop_recording: true,
    record_measurement: true,
    journal_refresh: true,
    journal_open_file: true,
    settings_aply: true,
    scenario_start: true,
    scenario_stop: true,
    scenario_pause: true,
    scenario_resume: true,
    scenario_emergency_stop: true,
    scenario_file_loaded: true,
    cancel_recording: true,
    journal_event: true
};
if (protocolTopics[topic]) return null;

// ╔══════════════════════════════════════════════════════════════════════════╗
// ║  Входящие топики (от Vue UI):                                            ║
// ║   "reread"               — опрос PX,VX,MS,MO,SO,AF,SR,SP,AC,DC,        ║
// ║                            TR[1],OL[1]                                   ║
// ║   "set_motion_params"    — задать SP, AC, DC (сохраняет в flow context) ║
// ║   "motor_on"             — MO=1                                          ║
// ║   "motor_off"            — MO=0                                          ║
// ║   "drive_stop"           — ST (быстрая остановка)                        ║
// ║   "drive_bg"             — BG (начать выполнение)                        ║
// ║   "driveInit"            — инициализация привода: настройка ДУ, MO=1,     ║
// ║                            один оборот для инициализации сумматора DSi    ║
// ║   "drive_home"           — HM[1]=1 (поиск нулевой метки)                ║
// ║   "set_absolute_position"— SP=<sp>;AC=<ac>;DC=<dc>;PA=<ticks>;BG        ║
// ║   "set_relative_position"— SP=<sp>;AC=<ac>;DC=<dc>;PR=<ticks>;BG        ║
// ║   "set_velocity"         — AC=<ac>;DC=<dc>;JV=<ticks>;BG               ║
// ║   "set_jv"               — AC=<ac>;DC=<dc>;JV=<ticks>;BG               ║
// ║   "set_jp"               — AC=<ac>;DC=<dc>;JP=<ticks>;BG               ║
// ║   "set_resolution"       — переключение пар головок ДУ согласно         ║
// ║                            мануалу раздел 4 (только при SO=0)           ║
// ║                                                                          ║
// ║  SP/AC/DC для PA и PR берутся из flow.context("motion_params"),         ║
// ║  куда они сохраняются при каждом "set_motion_params".                   ║
// ║  Дефолтные значения зависят от текущего разрешения (flow "resolution"). ║
// ╚══════════════════════════════════════════════════════════════════════════╝

// ──────────────────────────────────────────────────────────────────────────
// Утилиты
// ──────────────────────────────────────────────────────────────────────────

function cmdStr(cmd, value) {
    if (value === undefined || value === null) return cmd;
    return cmd + "=" + value;
}

function joinCmds() {
    var cmds = Array.isArray(arguments[0]) ? arguments[0] : Array.prototype.slice.call(arguments);
    return cmds.filter(Boolean).join(";");
}

function resolutionSetupCmds(r) {
    return [
        cmdStr("OL[1]", r.ol1),
        cmdStr("CA[18]", r.ca18),
        cmdStr("S1[5]", r.s1_5),
        cmdStr("KP[2]", r.kp2),
        cmdStr("SD", r.sd),
        cmdStr("QS", r.qs),
        cmdStr("VH[1]", r.vh1),
        cmdStr("VL[1]", r.vl1),
        cmdStr("VH[2]", r.vh2),
        cmdStr("ER[3]", r.er3),
        cmdStr("ER[2]", r.er2),
        cmdStr("TR[1]", r.tr1),
        cmdStr("TR[3]", r.tr3),
    ];
}

function configuredAngleDeg(value, fallback) {
    if (value === undefined || value === null || value === '') return fallback;
    if (typeof value !== "object") { var raw = Number(value); return isFinite(raw) ? Math.abs(raw) : fallback; }
    if (value.decimalDeg !== undefined && value.decimalDeg !== null && value.decimalDeg !== "") { var decimal = Number(value.decimalDeg); return isFinite(decimal) ? Math.abs(decimal) : fallback; }
    if (value.rad !== undefined && value.rad !== null && value.rad !== "") { var rad = Number(value.rad); return isFinite(rad) ? Math.abs(rad * 180 / Math.PI) : fallback; }
    var deg = Number(value.deg) || 0;
    var min = Math.abs(Number(value.min) || 0);
    var sec = Math.abs(Number(value.sec) || 0);
    var result = Math.abs(deg) + min / 60 + sec / 3600;
    return result > 0 ? result : fallback;
}

function driveToleranceDeg() {
    var settings = global.get("settings") || {};
    var advanced = settings.advanced || {};
    var tol = Number(advanced.speedRangeToleranceDegSec);
    return isFinite(tol) && tol >= 0 ? tol : 5;
}

function configuredSpeedRange(resKey) {
    var settings = global.get("settings") || {};
    var ranges = (settings.advanced && settings.advanced.rotationSpeedRanges) || global.get("drive_speed_ranges") || {};
    var range = ranges[resKey] || {};
    var defaultMin = (resKey === "high") ? (1 / 3600) : 10;
    var defaultMax = (resKey === "high") ? 20 : 360;
    var minDeg = configuredAngleDeg(range.min, defaultMin);
    var maxDeg = configuredAngleDeg(range.max, defaultMax);
    if (!(minDeg > 0)) minDeg = defaultMin;
    if (!(maxDeg > 0)) maxDeg = defaultMax;
    if (resKey === "low" && maxDeg > 360) maxDeg = 360;
    if (maxDeg < minDeg) { minDeg = defaultMin; maxDeg = defaultMax; }
    return { minDeg: minDeg, maxDeg: maxDeg };
}

function ticksPerDegByRes(resKey) {
    var r = RES[resKey] || RES.high;
    return r.ca18 / 360;
}

function effectiveResParams(resKey) {
    var base = RES[resKey] || RES.high;
    var r = Object.assign({}, base);
    var range = configuredSpeedRange(resKey);
    var ticksPerDeg = r.ca18 / 360;
    var maxDeg = range.maxDeg + driveToleranceDeg();
    if (resKey === "low" && maxDeg > 360) maxDeg = 360;
    r.vh2 = Math.min(Math.round(base.vh2), Math.floor(maxDeg * ticksPerDeg));
    return r;
}

function buildDriveLimits(resKey) {
    var r = effectiveResParams(resKey);
    var ticksPerDeg = ticksPerDegByRes(resKey);
    var range = configuredSpeedRange(resKey);
    var tol = driveToleranceDeg();
    var validateMinDeg = Math.max(0, range.minDeg - tol);
    var validateMaxDeg = range.maxDeg + tol;
    if (resKey === "low" && validateMaxDeg > 360) validateMaxDeg = 360;
    var speedMinTicks = Math.ceil(range.minDeg * ticksPerDeg);
    var speedMaxTicks = Math.min(Math.round(r.vh2), Math.floor(validateMaxDeg * ticksPerDeg));
    var speedMinValidateTicks = Math.ceil(validateMinDeg * ticksPerDeg);
    var speedMaxValidateTicks = speedMaxTicks;
    var accelMaxTicks = Math.min(Math.round(r.sd), Math.round(r.vh1), Math.round(r.vl1));
    return {
        resolution: resKey,
        ticks_per_deg: ticksPerDeg,
        speed_min_deg: range.minDeg,
        speed_max_deg: speedMaxTicks / ticksPerDeg,
        speed_configured_min_deg: range.minDeg,
        speed_configured_max_deg: range.maxDeg,
        speed_tolerance_deg: tol,
        speed_min_ticks: speedMinTicks,
        speed_max_ticks: speedMaxTicks,
        speed_min_validate_ticks: speedMinValidateTicks,
        speed_max_validate_ticks: speedMaxValidateTicks,
        low_absolute_max_ticks: resKey === "low" ? Math.floor(360 * ticksPerDeg) : null,
        accel_min_ticks: 0,
        accel_max_ticks: accelMaxTicks,
        accel_max_deg: accelMaxTicks / ticksPerDeg,
        decel_min_ticks: 0,
        decel_max_ticks: accelMaxTicks,
        decel_max_deg: accelMaxTicks / ticksPerDeg,
    };
}

function syncDriveLimits(resKey) {
    var limits = buildDriveLimits(resKey);
    flow.set("drive_limits", limits);
    global.set("drive_limits", limits);
    global.set("current_range", resKey);
    return limits;
}

function clampTicks(value, min, max) {
    var n = Math.round(Number(value) || 0);
    var lo = Math.round(Number(min) || 0);
    var hi = Math.round(Number(max) || 0);
    if (hi < lo) hi = lo;
    if (n < lo) return lo;
    if (n > hi) return hi;
    return n;
}

function preserveMotionParamsForResolution(params, oldLimits, newLimits, oldResKey) {
    params = params || {};
    var oldTicksPerDeg = Number(oldLimits && oldLimits.ticks_per_deg) || ticksPerDegByRes(oldResKey);
    var newTicksPerDeg = Number(newLimits && newLimits.ticks_per_deg) || ticksPerDegByRes(newLimits && newLimits.resolution);
    var oldSpDeg = Math.abs((Number(params.sp) || 0) / oldTicksPerDeg);
    var oldAcDeg = Math.abs((Number(params.ac) || 0) / oldTicksPerDeg);
    var oldDcDeg = Math.abs((Number(params.dc) || 0) / oldTicksPerDeg);
    var spTicks = oldSpDeg === 0 ? 0 : Math.round(oldSpDeg * newTicksPerDeg);
    if (spTicks !== 0) {
        spTicks = clampTicks(spTicks, newLimits.speed_min_ticks, newLimits.speed_max_ticks);
    }
    return {
        sp: spTicks,
        ac: clampTicks(Math.round(oldAcDeg * newTicksPerDeg), newLimits.accel_min_ticks, newLimits.accel_max_ticks),
        dc: clampTicks(Math.round(oldDcDeg * newTicksPerDeg), newLimits.decel_min_ticks, newLimits.decel_max_ticks),
    };
}

function validateUnsignedSpeed(name, value, limits, allowZero) {
    var n = Math.round(Number(value) || 0);
    if (n === 0 && allowZero) { return { ok: true, value: 0 }; }
    if (n < 0) { node.warn(name + ": speed cannot be negative"); return { ok: false }; }
    var minTicks = limits.speed_min_validate_ticks !== undefined ? limits.speed_min_validate_ticks : limits.speed_min_ticks;
    var maxTicks = limits.speed_max_validate_ticks !== undefined ? limits.speed_max_validate_ticks : limits.speed_max_ticks;
    if (limits.low_absolute_max_ticks && n > limits.low_absolute_max_ticks) {
        node.warn(name + ": value " + n + " ticks/s is above absolute 360 deg/s limit for low resolution");
        return { ok: false };
    }
    if (n < minTicks || n > maxTicks) {
        node.warn(name + ": value " + n + " ticks/s is outside allowed range [" + minTicks + ".." + maxTicks + "] for resolution " + limits.resolution);
        return { ok: false };
    }
    return { ok: true, value: n };
}

function validateSignedSpeed(name, value, limits, allowZero) {
    var n = Math.round(Number(value) || 0);
    var abs = Math.abs(n);
    if (abs === 0 && allowZero) { return { ok: true, value: 0 }; }
    var minTicks = limits.speed_min_validate_ticks !== undefined ? limits.speed_min_validate_ticks : limits.speed_min_ticks;
    var maxTicks = limits.speed_max_validate_ticks !== undefined ? limits.speed_max_validate_ticks : limits.speed_max_ticks;
    if (limits.low_absolute_max_ticks && abs > limits.low_absolute_max_ticks) {
        node.warn(name + ": value " + n + " ticks/s is above absolute 360 deg/s limit for low resolution");
        return { ok: false };
    }
    if (abs < minTicks || abs > maxTicks) {
        node.warn(name + ": value " + n + " ticks/s is outside allowed range +/-[" + minTicks + ".." + maxTicks + "] for resolution " + limits.resolution);
        return { ok: false };
    }
    return { ok: true, value: n };
}

function validateAccel(name, value, minTicks, maxTicks) {
    var n = Math.round(Number(value) || 0);
    if (n < minTicks || n > maxTicks) {
        node.warn(name + ": значение " + n + " тик/с² вне допустимого диапазона [" + minTicks + ".." + maxTicks + "]");
        return { ok: false };
    }
    return { ok: true, value: n };
}

// ──────────────────────────────────────────────────────────────────────────
// Константы разрешений (мануал, раздел 4, таблица 4.1)
// ──────────────────────────────────────────────────────────────────────────

var RES = {
    high: {
        ol1: 0,
        ca18: 262144000,
        s1_5: 50000000,
        kp2: 1e-6,
        sd: 131072000,   // 180 °/с²
        qs: 131072000,
        vh1: 131072000,
        vl1: 131072000,
        vh2: 34952533,    // max speed 48 deg/s (8 rpm high-resolution heads)
        er3: 131072000,   // окно ошибки позиции 180°
        er2: 131072000,   // окно ошибки скорости
        tr1: 7282,        // окно позиции 0.01°
        tr3: 364089,      // окно скорости 0.5°/с
        sp_def: 728177,      // 1 °/с
        ac_def: 364088,      // 0.5 °/с²
    },
    low: {
        ol1: 1,
        ca18: 6553600,
        s1_5: 7662835,
        kp2: 1e-5,
        sd: 3276800,     // 180 °/с²
        qs: 3276800,
        vh1: 3276800,
        vl1: 3276800,
        vh2: 6553600,     // макс. скорость
        er3: 3276800,
        er2: 3276800,
        tr1: 182,         // окно позиции 0.01°
        tr3: 9102,        // окно скорости 0.5°/с
        sp_def: 18204,       // 1 °/с
        ac_def: 9102,        // 0.5 °/с²
    },
};

// ──────────────────────────────────────────────────────────────────────────
// Текущее разрешение и параметры движения из flow context
// ──────────────────────────────────────────────────────────────────────────

var currentRes = flow.get("resolution") || "high";
var resParams = effectiveResParams(currentRes);
var currentLimits = syncDriveLimits(currentRes);

var storedParams = flow.get("motion_params") || {
    sp: resParams.sp_def,
    ac: resParams.ac_def,
    dc: resParams.ac_def,
};

// ──────────────────────────────────────────────────────────────────────────
// Маршрутизация
// ──────────────────────────────────────────────────────────────────────────

var payload = msg.payload;
var elmoCmd = null;
var elmoMeta = {};

switch (topic) {

    // ────────────────────────────────────────────────────────────────────
    // "reread" — опрос текущего состояния привода
    // Добавлен OL[1] для чтения текущего разрешения головок ДУ
    // ────────────────────────────────────────────────────────────────────
    case "reread":
        elmoCmd = joinCmds(
            "OL[1]",
            "TR[1]",
            "TR[3]",
            "AF",
            "SR",
            "MO",
            "SO",
            "PX",
            "VX",
            "SP",
            "AC",
            "DC",
            "JV",
            "JP",
            "SD",
            "QS",
            "VH[1]",
            "VL[1]",
            "VH[2]"
        );
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_motion_params" — задать SP, AC, DC
    // payload: { sp_ticks, ac_ticks, dc_ticks, jerk_ticks (опц.) }
    // jerk_ticks игнорируется (Elmo не имеет команды jerk напрямую)
    // ────────────────────────────────────────────────────────────────────
    case "set_motion_params":
        if (!payload) { node.warn("set_motion_params: нет payload"); return null; }

        var sp = Math.round(payload.sp_ticks !== undefined ? payload.sp_ticks : resParams.sp_def);
        var ac = Math.round(payload.ac_ticks !== undefined ? payload.ac_ticks : resParams.ac_def);
        var dc = Math.round(payload.dc_ticks !== undefined ? payload.dc_ticks : resParams.ac_def);
        var spCheck = validateUnsignedSpeed("set_motion_params/SP", sp, currentLimits, true);
        var acCheck = validateAccel("set_motion_params/AC", ac, currentLimits.accel_min_ticks, currentLimits.accel_max_ticks);
        var dcCheck = validateAccel("set_motion_params/DC", dc, currentLimits.decel_min_ticks, currentLimits.decel_max_ticks);
        if (!spCheck.ok || !acCheck.ok || !dcCheck.ok) return null;

        sp = spCheck.value;
        ac = acCheck.value;
        dc = dcCheck.value;

        flow.set("motion_params", { sp: sp, ac: ac, dc: dc });

        elmoCmd = joinCmds(
            cmdStr("SP", sp),
            cmdStr("AC", ac),
            cmdStr("DC", dc),
            "SP",
            "AC",
            "DC"
        );
        break;

    // ────────────────────────────────────────────────────────────────────
    // "motor_on" — включение привода
    // Мануал раздел 3: перед MO=1 биты SR[0-3] должны быть 0
    // ────────────────────────────────────────────────────────────────────
    case "motor_on":
        elmoCmd = joinCmds("MO=1", "MO", "SO", "SR");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "motor_off" — выключение привода
    // ────────────────────────────────────────────────────────────────────
    case "motor_off":
        elmoCmd = joinCmds("MO=0", "MO", "SO", "SR");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "drive_stop" — быстрая остановка с замедлением QS
    // ────────────────────────────────────────────────────────────────────
    case "drive_stop":
        elmoCmd = "ST";
        break;

    // ────────────────────────────────────────────────────────────────────
    // "drive_bg" — запуск последней заданной команды (PA/PR/JV/JP)
    // ────────────────────────────────────────────────────────────────────
    case "drive_bg":
        elmoCmd = "BG";
        break;

    // ────────────────────────────────────────────────────────────────────
    // "driveInit" — инициализация привода по приложению А к ТЗ.
    //
    // Назначение:
    //   1. Сопоставить шкалу инкрементного энкодера и полюса двигателя
    //      через штатный запуск привода MO=1.
    //   2. Выполнить один оборот планшайбы для инициализации сумматора DSi.
    //
    // payload опционален:
    //   { resolution: "high" | "low" } — если перед инициализацией нужно
    //   явно выбрать пару считывающих головок. Без payload используется
    //   текущее flow "resolution".
    // ────────────────────────────────────────────────────────────────────
    case "driveInit":
    case "drive_init":
        var initRes = RES[currentRes] ? currentRes : "high";
        if (payload && payload.resolution) {
            initRes = (payload.resolution === "low") ? "low" : "high";
        }

        var init = effectiveResParams(initRes);
        var initMotion = {
            sp: init.sp_def,
            ac: init.ac_def,
            dc: init.ac_def,
        };

        flow.set("resolution", initRes);
        flow.set("motion_params", initMotion);
        syncDriveLimits(initRes);

        elmoCmd = [
            "ST",
            "MO=0",
        ].concat(
            resolutionSetupCmds(init),
            [
                "AF=0",
                "EC=0",
                "SR",
                "MF",
                "EE[5]",
                "MO=1",
                "SO",
                cmdStr("SP", initMotion.sp),
                cmdStr("AC", initMotion.ac),
                cmdStr("DC", initMotion.dc),
                cmdStr("PR", init.ca18),
                "BG",
                "MS",
                "PX",
                "VX",
                "MO",
                "SO",
                "SR",
                "EC",
                "MF",
                "EE[5]",
                "OL[1]",
                "CA[18]",
                "SP",
                "AC",
                "DC",
            ]
        ).join(";\r");

        node.log("driveInit → " + initRes + " (one turn PR=" + init.ca18 + ")");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "drive_home" — поиск нулевой метки
    // Мануал раздел 6: только через TCP (не UDP)
    // ────────────────────────────────────────────────────────────────────
    case "drive_home":
        elmoCmd = "HM[1]=1;";
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_resolution" — переключение пар считывающих головок ДУ
    // payload: { resolution: "high" | "low" }
    //
    // Мануал раздел 4, алгоритм переключения головок:
    //   1. Выключить привод (SO=0) — проверяется на стороне UI
    //   2. Задать OL[1], CA[18], S1[5], KP[2], SD, QS,
    //      VH[1], VL[1], VH[2], ER[3], ER[2], TR[1], TR[3]
    //   3. Сохранить разрешение в flow context
    //   4. Пересчитать сохранённые SP/AC/DC в новое разрешение без изменения
    //      физических значений в градусах, с ограничением по допустимым пределам
    //
    // Команды разбиты на несколько строк \r для надёжного приёма по TCP.
    // ────────────────────────────────────────────────────────────────────
    case "set_resolution":
        if (!payload || !payload.resolution) {
            node.warn("set_resolution: нет payload.resolution");
            return null;
        }

        var newRes = (payload.resolution === "high") ? "high" : "low";
        var r = effectiveResParams(newRes);
        var oldLimits = currentLimits;
        var oldMotionParams = {
            sp: Number(storedParams.sp) || 0,
            ac: Number(storedParams.ac) || 0,
            dc: Number(storedParams.dc) || 0,
        };

        flow.set("resolution", newRes);
        var newLimits = syncDriveLimits(newRes);
        var preservedMotion = preserveMotionParamsForResolution(oldMotionParams, oldLimits, newLimits, currentRes);
        flow.set("motion_params", preservedMotion);

        elmoCmd = ["MO=0"].concat(resolutionSetupCmds(r), [
            cmdStr("SP", preservedMotion.sp),
            cmdStr("AC", preservedMotion.ac),
            cmdStr("DC", preservedMotion.dc),
            "SP",
            "AC",
            "DC",
        ]).join(";\r");

